mapper.update:
UPDATE meeting_candidates
SET place_name = #{placeName}, address = #{address}, latitude = #{latitude}, longitude = #{longitude}, is_active = #{isActive}, updated_at = NOW()
WHERE candidate_id = #{candidateId}

mapper.select:
SELECT candidate_id, meeting_id, proposer_participant_id, place_name, address, latitude, longitude, is_active, created_at, updated_at
FROM meeting_candidates
WHERE candidate_id = #{candidateId}

SELECT candidate_id, meeting_id, proposer_participant_id, place_name, address, latitude, longitude, is_active, created_at, updated_at
FROM meeting_candidates
WHERE meeting_id = #{meetingId} AND proposer_participant_id = #{participantId}
